import json

with open('/root/report.json', 'r') as f:
    report = json.load(f)

# Find any generators that violate constraints
violations = []
for gen in report['generator_dispatch']:
    if gen['output_MW'] < 0 or gen['output_MW'] > gen['pmax_MW']:
        violations.append(f"Gen {gen['id']}: output {gen['output_MW']} > pmax {gen['pmax_MW']}")
    if gen['reserve_MW'] < 0 or gen['reserve_MW'] > gen['pmax_MW']:
        violations.append(f"Gen {gen['id']}: reserve {gen['reserve_MW']} > pmax {gen['pmax_MW']}")
    if gen['output_MW'] + gen['reserve_MW'] > gen['pmax_MW']:
        violations.append(f"Gen {gen['id']}: output {gen['output_MW']} + reserve {gen['reserve_MW']} > pmax {gen['pmax_MW']}")

if violations:
    print("Constraint violations found:")
    for v in violations[:10]:
        print(f"  - {v}")
else:
    print("✓ No constraint violations found")
    print("\nVerifying generator dispatch + reserve <= pmax for all generators...")
    all_valid = True
    for gen in report['generator_dispatch']:
        total_used = gen['output_MW'] + gen['reserve_MW']
        if total_used > gen['pmax_MW'] + 0.01:  # Allow tiny rounding
            print(f"  Generator {gen['id']}: {total_used:.2f} > {gen['pmax_MW']}")
            all_valid = False
    if all_valid:
        print("✓ All generators satisfy output + reserve <= pmax")

